$ErrorActionPreference = 'Stop'
Add-Type -AssemblyName System.Drawing
$root = [IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'))
$masterPath = Join-Path $root 'assets\tenma-icon.png'
$icons = Join-Path $root 'src-tauri\icons'
$master = [Drawing.Bitmap]::FromFile($masterPath)
try {
  # Appx assets generated by the CLI use platform-specific padding and can retain
  # opaque edge pixels at small sizes. Redraw them from our transparent master.
  $files = @(Get-ChildItem -LiteralPath $icons -Filter 'Square*Logo.png') + @(Get-ChildItem -LiteralPath $icons -Filter 'StoreLogo.png')
  foreach ($file in $files) {
    $size = [Drawing.Bitmap]::FromFile($file.FullName)
    try {
      $width = $size.Width
      $height = $size.Height
    } finally { $size.Dispose() }
    $result = New-Object Drawing.Bitmap($width, $height, [Drawing.Imaging.PixelFormat]::Format32bppArgb)
    try {
      $graphics = [Drawing.Graphics]::FromImage($result)
      try {
        $graphics.CompositingMode = [Drawing.Drawing2D.CompositingMode]::SourceCopy
        $graphics.InterpolationMode = [Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
        $graphics.SmoothingMode = [Drawing.Drawing2D.SmoothingMode]::HighQuality
        $graphics.PixelOffsetMode = [Drawing.Drawing2D.PixelOffsetMode]::HighQuality
        $graphics.DrawImage($master, 0, 0, $width, $height)
      } finally { $graphics.Dispose() }
      # Prevent antialiasing at the outermost transparent corners from creating a box.
      $result.SetPixel(0, 0, [Drawing.Color]::Transparent)
      $result.SetPixel($width - 1, 0, [Drawing.Color]::Transparent)
      $result.SetPixel(0, $height - 1, [Drawing.Color]::Transparent)
      $result.SetPixel($width - 1, $height - 1, [Drawing.Color]::Transparent)
      $result.Save($file.FullName, [Drawing.Imaging.ImageFormat]::Png)
    } finally { $result.Dispose() }
  }
} finally { $master.Dispose() }
"PASS: redrawn $($files.Count) Windows Appx PNGs from the transparent, tightly cropped master"
